package com.xyz.question_bank_management_system.modules.course.service.impl;
import com.fasterxml.jackson.databind.ObjectMapper;import com.xyz.question_bank_management_system.config.CorrelationContext;import com.xyz.question_bank_management_system.exception.*;import com.xyz.question_bank_management_system.modules.course.entity.ExamEligibilitySnapshot;import com.xyz.question_bank_management_system.modules.course.mapper.*;import com.xyz.question_bank_management_system.modules.course.service.*;import com.xyz.question_bank_management_system.modules.profile.service.ProfileQueryService;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.LocalDateTime;import java.util.*;
@Service @RequiredArgsConstructor public class LearningOutcomeServiceImpl implements CourseProgressService,ExamEligibilityService,LearningReportService {private final CourseMapper courseMapper;private final LearningOutcomeMapper mapper;private final ProfileQueryService profileQuery;private final ObjectMapper objectMapper;
 @Override public Map<String,Object> progress(Long userId,Long courseId){if(courseMapper.selectById(courseId)==null)throw BizException.of(ErrorCode.NOT_FOUND,"课程不存在");int total=mapper.totalKnowledge(courseId),completed=mapper.completedKnowledge(userId,courseId,new BigDecimal("0.80"),new BigDecimal("0.60"));BigDecimal rate=total==0?BigDecimal.ZERO:BigDecimal.valueOf(completed).divide(BigDecimal.valueOf(total),4,RoundingMode.HALF_UP);return Map.of("courseId",courseId,"totalCoreKnowledgePoints",total,"completedKnowledgePoints",completed,"completionRate",rate,"masteryThreshold",new BigDecimal("0.80"),"confidenceThreshold",new BigDecimal("0.60"),"ruleVersion","course_completion_v1");}
 @Override @Transactional public Map<String,Object> eligibility(Long userId,Long goalId){List<Map<String,Object>> req=mapper.requirements(goalId);if(req.isEmpty())return Map.of("goalId",goalId,"eligible",false,"reason","REQUIREMENT_MISSING","courses",List.of());List<Map<String,Object>> courses=new ArrayList<>();boolean eligible=true;for(Map<String,Object> r:req){Long c=((Number)(r.containsKey("course_id")?r.get("course_id"):r.get("courseId"))).longValue();Map<String,Object> p=progress(userId,c);boolean pass=((BigDecimal)p.get("completionRate")).compareTo(new BigDecimal("0.90"))>=0;eligible&=pass;Map<String,Object>x=new LinkedHashMap<>(p);x.put("eligible",pass);courses.add(x);}try{Map<String,Object> result=new LinkedHashMap<>();result.put("goalId",goalId);result.put("eligible",eligible);result.put("requiredCompletionRate",new BigDecimal("0.90"));result.put("courses",courses);result.put("ruleVersion","exam_eligibility_v1");ExamEligibilitySnapshot s=new ExamEligibilitySnapshot();s.setSnapshotCode("elig_"+UUID.randomUUID().toString().replace("-",""));s.setUserId(userId);s.setGoalId(goalId);s.setEligible(eligible?1:0);s.setCourseVersionsJson("{}");s.setProfileVersionsJson(objectMapper.writeValueAsString(courses.stream().map(x->Map.of("courseId",x.get("courseId"),"profile",profileQuery.summary(userId,((Number)x.get("courseId")).longValue()).get("profileVersion"))).toList()));s.setRuleVersion("exam_eligibility_v1");s.setResultJson(objectMapper.writeValueAsString(result));s.setCorrelationId(CorrelationContext.get());s.setCalculatedAt(LocalDateTime.now());mapper.insertEligibility(s);result.put("snapshotCode",s.getSnapshotCode());return result;}catch(Exception ex){throw new IllegalStateException(ex);}}
 @Override public Map<String,Object> report(Long userId,Long courseId){Map<String,Object> m=new LinkedHashMap<>();m.put("courseId",courseId);m.put("progress",progress(userId,courseId));m.put("profileSummary",profileQuery.summary(userId,courseId));m.put("masteryChanges",mapper.masteryHistory(userId,courseId));m.put("pathChanges",mapper.pathHistory(userId,courseId));m.put("resourceActions",mapper.resourceActions(userId,courseId));return m;}
}
